// Block (composition) — account settings assembled from form Components.
// Arranges only; composes Form/TextField/Switch/Select/Button/Alert/Separator/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Switch } from "../components/Switch";
import { Select, SelectItem } from "../components/Select";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import { Separator } from "../components/Separator";
import "./SettingsForm.css";

export interface SettingsFormProps {
  /** Heading shown above the settings. */
  heading?: string;
  /** Called with the submitted settings. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Form-level error, shown above the sections. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function SettingsForm({
  heading,
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: SettingsFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      displayName: String(data.get("displayName") ?? ""),
      email: String(data.get("email") ?? ""),
      notifications: String(data.get("notifications") ?? ""),
      theme: String(data.get("theme") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-settingsform ${className}` : "sd-settingsform"}
    >
      <Stack gap="large" className="sd-settingsform__content">
        {heading && (
          <>
            <h1 className="sd-settingsform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-settingsform__profile">
          <>
            <h2 className="sd-settingsform__section-heading sd-type-title-medium">Profile</h2>
          </>
          <TextField label="Display name" name="displayName" autoComplete="name" isRequired />
          <TextField label="Email" name="email" type="email" autoComplete="email" isRequired />
        </Stack>
        {/* The two sections part across a rule: an edge is a step, so `large` holds over their
            `medium`. Air alone would need `x-large` here and then a rung the ladder does not have
            for the Settings page above it (token-contract.md § By relationship). */}
        <Separator />
        <Stack gap="medium" className="sd-settingsform__preferences">
          <>
            <h2 className="sd-settingsform__section-heading sd-type-title-medium">Preferences</h2>
          </>
          {/* The track is a box, so it sits on the fields' box line (component-contract.md §6 rule 8). */}
          <Switch name="notifications">Email notifications</Switch>
          <Select label="Theme" name="theme" defaultSelectedKey="system" isRequired>
            <SelectItem id="light">Light</SelectItem>
            <SelectItem id="dark">Dark</SelectItem>
            <SelectItem id="system">System</SelectItem>
          </Select>
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Save
        </Button>
      </Stack>
    </Form>
  );
}

/* SettingsForm.css — arrangement only; Component look stays with its owners. */
/* A Panel: it sits beside other sections on a settings page, so its width is the page's
   (block-contract.md §1b), so it runs to the page edge with every section around it. The narrow,
   centred presentation belongs to its story, which sets it. */
.sd-settingsform {
  width: 100%;
}

.sd-settingsform__heading,
.sd-settingsform__section-heading {
  margin: 0;
}
